import React from "react";
import { ShortcutsHelp } from "./utils/keyboardShortcuts";
import "./utils/keyboardShortcuts.css";
import Tutorial from "./components/Tutorial";

function Home({ authToken, userEmail, onNavigate, onLogout, darkMode, toggleDarkMode }) {
  const [showNavDropdown, setShowNavDropdown] = React.useState(false);
  const [showUserDropdown, setShowUserDropdown] = React.useState(false);
  const [userDropdownTimeout, setUserDropdownTimeout] = React.useState(null);
  const [showFabMenu, setShowFabMenu] = React.useState(false);
  const [showShortcuts, setShowShortcuts] = React.useState(false);
  const [showHelpModal, setShowHelpModal] = React.useState(false);
  const [showTutorial, setShowTutorial] = React.useState(false);
  const [unreadCount, setUnreadCount] = React.useState(0);

  // Check if user has seen tutorial on first visit
  React.useEffect(() => {
    const tutorialCompleted = localStorage.getItem('tutorial_completed');
    if (!tutorialCompleted && authToken) {
      // Show tutorial for first-time users
      setShowTutorial(true);
    }
    
    // Fetch unread notifications
    const fetchUnreadNotifications = async () => {
      try {
        const res = await fetch(`http://localhost:8000/notifications/${userEmail}`);
        const data = await res.json();
        if (data.status === "success") {
          setUnreadCount(data.unread_count);
        }
      } catch (err) {
        console.error("Error fetching notifications:", err);
      }
    };

    if (userEmail) {
      fetchUnreadNotifications();
    }
  }, [authToken, userEmail]);

  const handleUserMouseEnter = () => {
    if (userDropdownTimeout) clearTimeout(userDropdownTimeout);
    setShowUserDropdown(true);
  };

  const handleUserMouseLeave = () => {
    const timeout = setTimeout(() => setShowUserDropdown(false), 200);
    setUserDropdownTimeout(timeout);
  };

  const handleSettings = () => {
    onNavigate("app-settings");
  };

  const handleHelp = () => {
    setShowHelpModal(true);
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh" }}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo" onClick={() => onNavigate("main")} style={{ cursor: "pointer" }}>
            🍳 SmartChef
          </div>
          <div className="nav-buttons">
            {authToken ? (
              <>
                {/* Right side - Menu & User */}
                <div style={{ display: "flex", gap: "0.8rem", alignItems: "center", marginLeft: "auto", marginRight: "-0.5rem" }}>
                  {/* Navigation Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={() => setShowNavDropdown(true)}
                    onMouseLeave={() => setShowNavDropdown(false)}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ padding: "0.7rem 1.2rem", fontSize: "1.5rem" }}
                    >
                      ☰
                    </button>
                    {showNavDropdown && (
                      <div className="nav-dropdown">
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("dashboard");
                            setShowNavDropdown(false);
                          }}
                        >
                          📈 Dashboard
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("history");
                            setShowNavDropdown(false);
                          }}
                        >
                          📊 History
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("goals");
                            setShowNavDropdown(false);
                          }}
                        >
                          🎯 Goals
                        </button>
                      </div>
                    )}
                  </div>
                  
                  <div style={{
                    width: "1px",
                    height: "30px",
                    background: "rgba(255,255,255,0.3)",
                    margin: "0 0.5rem"
                  }}></div>

                  {/* Notifications Bell */}
                  <button
                    className="btn btn-outline"
                    onClick={() => onNavigate('notifications')}
                    style={{ 
                      padding: "0.7rem 1.2rem", 
                      fontSize: "1.5rem", 
                      background: "rgba(255,255,255,0.2)",
                      position: "relative"
                    }}
                    title="Notifications"
                  >
                    🔔
                    {unreadCount > 0 && (
                      <span style={{
                        position: "absolute",
                        top: "-5px",
                        right: "-5px",
                        background: "#2d5a3d",
                        color: "white",
                        borderRadius: "50%",
                        width: "24px",
                        height: "24px",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontSize: "0.75rem",
                        fontWeight: "700",
                        border: "2px solid white"
                      }}>
                        {unreadCount}
                      </span>
                    )}
                  </button>
                  
                  {/* User Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={handleUserMouseEnter}
                    onMouseLeave={handleUserMouseLeave}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ 
                        display: "flex",
                        alignItems: "center",
                        gap: "0.5rem"
                      }}
                    >
                      👤 {userEmail}
                      <span style={{ 
                        fontSize: "0.7rem",
                        transition: "transform 0.3s",
                        display: "inline-block",
                        transform: showUserDropdown ? "rotate(90deg)" : "rotate(0deg)"
                      }}>►</span>
                    </button>
                    {showUserDropdown && (
                      <div className="user-dropdown">
                        <button className="user-dropdown-item" onClick={() => alert('🚧 Profile - Coming soon!')}>
                          <span className="dropdown-icon">👤</span>
                          Profile
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("personal-data");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">📊</span>
                          Personal Data
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("account-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">🔑</span>
                          Account Settings
                        </button>

                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("app-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">⚙️</span>
                          App Settings
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          setShowTutorial(true);
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">🎓</span>
                          Replay Tutorial
                        </button>
                        
                        <div className="user-dropdown-divider"></div>
                        <button className="user-dropdown-item logout-item" onClick={onLogout}>
                          <span className="dropdown-icon">🚪</span>
                          Logout
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </>
            ) : (
              <div style={{ display: "flex", gap: "0.5rem", marginLeft: "auto" }}>
                <button
                  className="btn btn-outline"
                  onClick={() => onNavigate("login")}
                >
                  Login
                </button>
                <button
                  className="btn btn-secondary"
                  onClick={() => onNavigate("register")}
                >
                  Register
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content Container */}
      <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "3rem 2rem" }}>
        {/* Hero Section */}
        <div style={{ textAlign: "center", marginBottom: "5rem" }}>
          <h1 style={{ 
            fontSize: "3.2rem", 
            fontWeight: "700", 
            color: "#1a1a1a",
            marginBottom: "1rem",
            textShadow: "none"
          }}>
            Know what you're <span style={{ color: "#2d5a3d" }}>eating</span>
          </h1>
          <p style={{ 
            fontSize: "1.15rem", 
            color: "#666",
            fontWeight: "400",
            maxWidth: "700px",
            margin: "0 auto",
            lineHeight: "1.7"
          }}>
            Photograph your meals and get instant nutrition insights. Track your progress with a clear, intuitive dashboard.
          </p>
        </div>

        {/* Main Features - Clean Cards */}
        <div style={{ marginBottom: "5rem" }}>
          {/* Feature 1 */}
          <div style={{ 
            display: "flex", 
            alignItems: "center", 
            gap: "4rem", 
            marginBottom: "4rem",
            flexWrap: "wrap"
          }}>
            <div style={{ 
              flex: "1", 
              minWidth: "280px",
              padding: "2rem",
              background: "#f8f8f8",
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              height: "180px"
            }}>
              <div style={{ fontSize: "4.5rem" }}>📸</div>
            </div>
            <div style={{ flex: "1.2", minWidth: "280px" }}>
              <h2 style={{ 
                fontSize: "1.7rem", 
                color: "#1a1a1a", 
                marginBottom: "0.8rem",
                fontWeight: "600"
              }}>
                Instant recognition
              </h2>
              <p style={{ 
                fontSize: "1rem", 
                color: "#666", 
                lineHeight: "1.7",
                marginBottom: "1rem"
              }}>
                Snap a photo of any meal. Our recognition technology identifies ingredients accurately and instantly.
              </p>
            </div>
          </div>

          {/* Feature 2 */}
          <div style={{ 
            display: "flex", 
            alignItems: "center", 
            gap: "4rem", 
            marginBottom: "4rem",
            flexWrap: "wrap",
            flexDirection: "row-reverse"
          }}>
            <div style={{ 
              flex: "1", 
              minWidth: "280px",
              padding: "2rem",
              background: "#f8f8f8",
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              height: "180px"
            }}>
              <div style={{ fontSize: "4.5rem" }}>📊</div>
            </div>
            <div style={{ flex: "1.2", minWidth: "280px" }}>
              <h2 style={{ 
                fontSize: "1.7rem", 
                color: "#1a1a1a", 
                marginBottom: "0.8rem",
                fontWeight: "600"
              }}>
                Complete nutrition data
              </h2>
              <p style={{ 
                fontSize: "1rem", 
                color: "#666", 
                lineHeight: "1.7",
                marginBottom: "1rem"
              }}>
                Get detailed breakdowns: calories, protein, carbs, fat, fiber, and more for each ingredient analyzed.
              </p>
            </div>
          </div>

          {/* Feature 3 */}
          <div style={{ 
            display: "flex", 
            alignItems: "center", 
            gap: "4rem", 
            marginBottom: "4rem",
            flexWrap: "wrap"
          }}>
            <div style={{ 
              flex: "1", 
              minWidth: "280px",
              padding: "2rem",
              background: "#f8f8f8",
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              height: "180px"
            }}>
              <div style={{ fontSize: "4.5rem" }}>📈</div>
            </div>
            <div style={{ flex: "1.2", minWidth: "280px" }}>
              <h2 style={{ 
                fontSize: "1.7rem", 
                color: "#1a1a1a", 
                marginBottom: "0.8rem",
                fontWeight: "600"
              }}>
                Track progress
              </h2>
              <p style={{ 
                fontSize: "1rem", 
                color: "#666", 
                lineHeight: "1.7",
                marginBottom: "1rem"
              }}>
                Monitor your intake with an interactive dashboard. Set goals, view statistics, and maintain streaks.
              </p>
            </div>
          </div>
        </div>

        {/* Additional Benefits - Minimal Grid */}
        <div style={{ 
          marginBottom: "4rem"
        }}>
          <h2 style={{ 
            textAlign: "left", 
            fontSize: "1.8rem", 
            color: "#1a1a1a", 
            marginBottom: "2.5rem",
            fontWeight: "600"
          }}>
            More features
          </h2>
          <div style={{ 
            display: "grid", 
            gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", 
            gap: "2rem"
          }}>
            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>🔒</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  Secure
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  2FA protection and secure cloud storage
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>⚙️</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  Customizable
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  5 themes, units, languages and more
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>🔥</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  Streaks
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  Motivate yourself with daily streaks
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>📄</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  Export
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  Generate PDF reports anytime
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>📚</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  History
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  Keep all meals with advanced filters
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "1rem" }}>
              <div style={{ fontSize: "2rem", flexShrink: 0 }}>⚖️</div>
              <div>
                <h3 style={{ fontSize: "1rem", marginBottom: "0.4rem", color: "#1a1a1a", fontWeight: "600" }}>
                  Weight tracking
                </h3>
                <p style={{ color: "#888", fontSize: "0.9rem", lineHeight: "1.5" }}>
                  Monitor progress with charts
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* CTA Section */}
        {!authToken ? (
          <div className="card" style={{ 
            maxWidth: "600px", 
            margin: "4rem auto 0", 
            textAlign: "center",
            padding: "3rem",
            background: "white",
            boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
            borderRadius: "12px"
          }}>
            <h2 style={{ fontSize: "1.8rem", color: "#1a1a1a", marginBottom: "1rem", fontWeight: "600" }}>
              Start free
            </h2>
            <p style={{ fontSize: "1rem", color: "#666", marginBottom: "2rem", lineHeight: "1.6" }}>
              Create an account to start analyzing your meals
            </p>
            <div style={{ display: "flex", gap: "1rem", justifyContent: "center", flexWrap: "wrap" }}>
              <button
                className="btn btn-primary"
                onClick={() => onNavigate("register")}
                style={{ 
                  padding: "0.9rem 2rem", 
                  fontSize: "1rem",
                  background: "#1a1a1a",
                  color: "white",
                  border: "none",
                  borderRadius: "6px",
                  fontWeight: "500",
                  cursor: "pointer"
                }}
              >
                Sign up
              </button>
              <button
                className="btn btn-outline"
                onClick={() => onNavigate("login")}
                style={{ 
                  padding: "0.9rem 2rem", 
                  fontSize: "1rem",
                  background: "transparent",
                  color: "#1a1a1a",
                  border: "1.5px solid #ddd",
                  borderRadius: "6px",
                  fontWeight: "500",
                  cursor: "pointer"
                }}
              >
                Login
              </button>
            </div>
          </div>
        ) : (
          <div style={{ textAlign: "center", marginTop: "4rem" }}>
            <div style={{
              background: "linear-gradient(135deg, #2d5a3d 0%, #1a4d2e 100%)",
              color: "white",
              padding: "2.5rem",
              borderRadius: "12px",
              boxShadow: "0 8px 24px rgba(0,0,0,0.15)"
            }}>
              <h2 style={{ fontSize: "2rem", marginBottom: "0.8rem", fontWeight: "600" }}>
                Analyze your next meal
              </h2>
              <p style={{ fontSize: "1.05rem", marginBottom: "2rem", opacity: 0.95, lineHeight: "1.6" }}>
                Upload a photo to see complete nutrition information
              </p>
              <button
                className="btn"
                onClick={() => onNavigate("analyze-food")}
                style={{ 
                  background: "white",
                  color: "#2d5a3d",
                  padding: "0.95rem 2.5rem",
                  fontSize: "1rem",
                  fontWeight: "600",
                  border: "none",
                  borderRadius: "6px",
                  cursor: "pointer",
                  transition: "all 0.3s ease"
                }}
                onMouseEnter={(e) => e.target.style.opacity = "0.9"}
                onMouseLeave={(e) => e.target.style.opacity = "1"}
              >
                📸 Analyze now
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Floating Action Button with Expandable Menu */}
      <div className="fab-container">
        {/* Menu Items (appear when expanded) */}
        <button
          className={`fab-menu-item fab-menu-item-1 ${showFabMenu ? 'show' : ''}`}
          onClick={toggleDarkMode}
          title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
        <button
          className={`fab-menu-item fab-menu-item-2 ${showFabMenu ? 'show' : ''}`}
          onClick={handleSettings}
          title="Settings"
        >
          ⚙️
        </button>
        <button
          className={`fab-menu-item fab-menu-item-3 ${showFabMenu ? 'show' : ''}`}
          onClick={handleHelp}
          title="Help & Support"
        >
          ❓
        </button>
        <button
          className={`fab-menu-item fab-menu-item-4 ${showFabMenu ? 'show' : ''}`}
          onClick={() => setShowShortcuts(true)}
          title="Keyboard Shortcuts (press ?)"
        >
          ⌨️
        </button>
        
        {/* Main FAB Button */}
        <button
          className={`fab-main ${showFabMenu ? 'active' : ''}`}
          onClick={() => setShowFabMenu(!showFabMenu)}
          title="Menu"
        >
          <span className="fab-icon">{showFabMenu ? '×' : '+'}</span>
        </button>
      </div>

      {/* Keyboard Shortcuts Help Modal */}
      {showShortcuts && (
        <ShortcutsHelp 
          onClose={() => setShowShortcuts(false)}
          customShortcuts={{
            'h': { description: 'Mergi la Home (acum)', action: 'navigate-home' }
          }}
        />
      )}

      {/* Help & Support Modal */}
      {showHelpModal && (
        <div style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "rgba(0, 0, 0, 0.6)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 10000
        }}>
          <div style={{
            background: "white",
            borderRadius: "12px",
            padding: "2rem",
            maxWidth: "500px",
            width: "90%",
            boxShadow: "0 10px 40px rgba(0, 0, 0, 0.3)",
            position: "relative"
          }}>
            {/* Close Button (X) */}
            <button
              onClick={() => setShowHelpModal(false)}
              style={{
                position: "absolute",
                top: "1rem",
                right: "1rem",
                background: "none",
                border: "none",
                fontSize: "1.8rem",
                cursor: "pointer",
                color: "#999",
                width: "40px",
                height: "40px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transition: "all 0.2s ease"
              }}
              onMouseEnter={(e) => {
                e.target.style.color = "#1a1a1a";
              }}
              onMouseLeave={(e) => {
                e.target.style.color = "#999";
              }}
            >
              ×
            </button>

            {/* Modal Content */}
            <h2 style={{ 
              fontSize: "1.6rem", 
              color: "#1a1a1a", 
              marginBottom: "1.5rem",
              paddingRight: "2rem",
              fontWeight: "600"
            }}>
              Help & Support
            </h2>

            <div style={{ color: "#666", lineHeight: "1.8" }}>
              <p style={{ marginBottom: "1rem", fontWeight: "500", color: "#1a1a1a" }}>
                Need help?
              </p>
              <ul style={{ marginBottom: "1.5rem", paddingLeft: "1.5rem" }}>
                <li style={{ marginBottom: "0.5rem" }}>📧 <strong>Email:</strong> support@smartchef.ro</li>
                <li style={{ marginBottom: "0.5rem" }}>🐛 <strong>Report bugs</strong> on GitHub</li>
              </ul>

              <p style={{ marginBottom: "1rem", fontWeight: "500", color: "#1a1a1a" }}>
                Quick tips:
              </p>
              <ul style={{ paddingLeft: "1.5rem" }}>
                <li style={{ marginBottom: "0.5rem" }}>📸 Use clear, well-lit food photos</li>
                <li style={{ marginBottom: "0.5rem" }}>🌙 Try dark mode for better viewing</li>
                <li style={{ marginBottom: "0.5rem" }}>📄 Export analyses as PDF</li>
                <li>⭐ Organize favorite meals</li>
              </ul>
            </div>

            {/* OK Button */}
            <button
              onClick={() => setShowHelpModal(false)}
              style={{
                marginTop: "2rem",
                width: "100%",
                padding: "0.9rem",
                background: "#1a1a1a",
                color: "white",
                border: "none",
                borderRadius: "6px",
                fontSize: "1rem",
                fontWeight: "500",
                cursor: "pointer",
                transition: "all 0.3s ease"
              }}
              onMouseEnter={(e) => {
                e.target.style.background = "#333";
              }}
              onMouseLeave={(e) => {
                e.target.style.background = "#1a1a1a";
              }}
            >
              Close
            </button>
          </div>
        </div>
      )}

      {/* Onboarding Tutorial */}
      {showTutorial && (
        <Tutorial onComplete={() => setShowTutorial(false)} />
      )}
    </div>
  );
}

export default Home;
